def get_cached_cdef(
    module_name: str = "pynng._nng",
    *,
    tls_enabled: bool = True,
) -> tuple[str, list[str]]:
    """Return pre-generated (cdef_string, headers_list) for the target CFFI module."""
    if module_name == "pynng._nng_v2":
        if tls_enabled:
            return CDEF_V2_TLS, list(HEADERS_V2_TLS)
        return CDEF_V2_NO_TLS, list(HEADERS_V2_NO_TLS)
    if tls_enabled:
        return CDEF_V1_TLS, list(HEADERS_V1_TLS)
    return CDEF_V1_NO_TLS, list(HEADERS_V1_NO_TLS)
